namespace SerbiaID;

/// Texts of the vehicle registration card and the card diagnostics, all languages in one table
/// (order: ru, en, sr, hu, sq, sk, ro, hr, uk, be; Serbian Cyrillic is derived from the Latin text).
/// Same texts as LocalizationCards.swift and the Android strings.xml files.
internal static class LocCards
{
    private static int Index(Lang l) => l switch
    {
        Lang.ru => 0, Lang.en => 1, Lang.sr or Lang.srCyrl => 2, Lang.hu => 3, Lang.sq => 4, Lang.sk => 5, Lang.ro => 6,
        Lang.hr => 7, Lang.uk => 8, Lang.be => 9, _ => 1,
    };

    public static string Get(Lang lang, string key)
    {
        if (!Table.TryGetValue(key, out var v)) return key;
        if (lang == Lang.srCyrl) return SerbianScript.Cyrillic(v[2]);
        return v[Index(lang)];
    }

